WITH RankedPosts AS (SELECT p.Id AS PostId, p.Title, p.CreationDate, p.OwnerUserId, p.ViewCount, ROW_NUMBER() OVER (PARTITION BY p.OwnerUserId ORDER BY p.CreationDate DESC NULLS FIRST) AS Rank FROM Posts AS p WHERE p.PostTypeId = 1), UserStats AS (SELECT u.Id AS UserId, u.DisplayName, u.Reputation, COUNT(DISTINCT p.Id) AS TotalQuestions, SUM(CASE WHEN p.Score > 0 THEN 1 ELSE 0 END) AS PositiveQuestions FROM Users AS u LEFT JOIN Posts AS p ON u.Id = p.OwnerUserId AND p.PostTypeId = 1 GROUP BY u.Id, u.DisplayName, u.Reputation), UserBadges AS (SELECT b.UserId, GROUP_CONCAT(b.Name, ', ') AS Badges FROM Badges AS b WHERE b.Class = 1 GROUP BY b.UserId) SELECT us.UserId, us.DisplayName, us.Reputation, us.TotalQuestions, us.PositiveQuestions, COALESCE(ub.Badges, 'No Gold Badges') AS GoldBadges, rp.Title AS LatestPostTitle, rp.CreationDate AS LatestPostDate FROM UserStats AS us LEFT JOIN UserBadges AS ub ON us.UserId = ub.UserId LEFT JOIN RankedPosts AS rp ON us.UserId = rp.OwnerUserId AND rp.Rank = 1 WHERE us.Reputation > 1000 ORDER BY us.Reputation DESC NULLS FIRST, us.TotalQuestions DESC NULLS FIRST FETCH FIRST 10 ROWS ONLY